d=read('/input/data')
nodes=d['nodes']
edges=d['edges']
levels={}
remaining=list(nodes)
for n in nodes:
    putmap(levels,n,0)
# Iterative relaxation bounded by number of nodes; DAG longest paths need at most n-1 edge passes.
for i in range(len(nodes)):
    for e in edges:
        u=e['u']
        v=e['v']
        putmap(levels,v,max(get(levels,v,0),get(levels,u,0)+1))
mx=max([get(levels,n,0) for n in nodes]) if len(nodes)>0 else -1
layers=[]
for k in range(mx+1):
    layers=layers+[sorted([n for n in nodes if get(levels,n,0)==k])]
